recorder:
// Recorder for node-files-utf8-stream.controls.json. Every scenario is the body of an async function of (fs, h)
// that the test runs again, unchanged, against the emulated fs. Run with Node 24.18.1 on a tmpfs:
//   docker run --rm --tmpfs /work -v "$PWD":/w:ro node:24.18.1-alpine node /w/record.cjs /w/sc > node-files-utf8-stream.controls.json
// `lifetime` holds whole programs: each ran as its own process, and what it printed and how it ended is recorded.
const fs = require("fs"), path = require("path"), child = require("child_process");
const dir = process.argv[2], scenarios = {};
function describe(e) {
  if (!(e instanceof Error)) return { thrown: String(e) };
  const d = { name: e.name, ctor: e.constructor.name, message: e.message };
  for (const k of ["code", "errno", "syscall", "path", "dest"]) if (e[k] !== undefined) d[k] = e[k];
  return d;
}
const EVENTS = ["ready", "drain", "drop", "write", "finish", "close", "error"];
let uncaught = [];
process.on("uncaughtException", error => { uncaught.push(describe(error)); });
function helpers(base) {
  const show = value => Buffer.isBuffer(value) ? { hex: value.toString("hex") } : value instanceof Error ? describe(value) : value;
  return {
    Buffer, dir: base, uncaught, err: describe, show,
    attempt(fn) { try { return { ok: fn() }; } catch (e) { return { error: describe(e) }; } },
    // Every event of the stream, in order, with its arguments.
    log(stream, events = EVENTS) { const seen = []; for (const name of events) stream.on(name, (...args) => { seen.push([name, ...args.map(show)]); }); return seen; },
    event: (stream, name) => new Promise(resolve => { stream.once(name, (...args) => { resolve(args.map(show)); }); }),
    // Long enough for the thread pool to finish what is in flight; the replay runs its queued work instead.
    turns: () => new Promise(resolve => setTimeout(resolve, 40)),
    // Lets `milliseconds` of timers pass; the replay advances its own clock.
    sleep: milliseconds => new Promise(resolve => setTimeout(resolve, milliseconds + 40)),
    text: file => fs.readFileSync(file, "utf8"),
    mode: file => fs.statSync(file).mode & 0o777,
    state: s => ({ mode: s.mode === undefined ? "undefined" : s.mode, file: s.file, fd: s.fd === -1 ? -1 : typeof s.fd === "number" ? "open" : typeof s.fd, minLength: s.minLength, maxLength: s.maxLength, writing: s.writing,
      sync: s.sync, fsync: s.fsync, append: s.append, periodicFlush: s.periodicFlush, contentMode: s.contentMode, mkdir: s.mkdir }),
  };
}
const LIFETIME = {
  // An asynchronous write in flight keeps the process alive until the file holds everything.
  "pending-write": `const fs = require("fs"); const s = new fs.Utf8Stream({ dest: "/work/lifetime/a.log" }); for (let i = 0; i < 64; i += 1) s.write("x".repeat(16383) + "\\n"); process.on("exit", () => console.log(JSON.stringify({ size: fs.statSync("/work/lifetime/a.log").size, writing: s.writing })));`,
  // What is below minLength at exit is never written, and the periodic timer does not hold the process.
  "buffered-at-exit": `const fs = require("fs"); const started = Date.now(); const s = new fs.Utf8Stream({ dest: "/work/lifetime/b.log", minLength: 100, periodicFlush: 60000 }); s.write("never written\\n"); process.on("exit", () => console.log(JSON.stringify({ size: fs.statSync("/work/lifetime/b.log").size, early: Date.now() - started < 5000 })));`,
  // The retry timer of a refused write is referenced: the process waits for it.
  "retry-timer": `const fs = require("fs"); let fail = true; const s = new fs.Utf8Stream({ dest: "/work/lifetime/c.log", fs: { write(fd, data, encoding, callback) { if (fail) { fail = false; callback(Object.assign(new Error("again"), { code: "EAGAIN" })); return; } fs.write(fd, data, null, encoding, callback); } } }); s.write("after the retry\\n"); process.on("exit", () => console.log(JSON.stringify({ text: fs.readFileSync("/work/lifetime/c.log", "utf8") })));`,
  // A pending flush callback alone holds nothing: the write it waits for does.
  "pending-flush": `const fs = require("fs"); const s = new fs.Utf8Stream({ dest: "/work/lifetime/d.log", minLength: 100 }); s.write("flushed\\n"); let called = false; s.flush(() => { called = true; }); process.on("exit", () => console.log(JSON.stringify({ called, text: fs.readFileSync("/work/lifetime/d.log", "utf8") })));`,
  // The periodic flush passes null as the callback, which the flush refuses: an uncaught exception each period.
  "periodic-flush-crash": `const fs = require("fs"); const s = new fs.Utf8Stream({ dest: "/work/lifetime/e.log", minLength: 100, periodicFlush: 50 }); s.write("x\\n"); setTimeout(() => console.log("survived"), 200);`,
};
(async () => {
  for (const file of fs.readdirSync(dir).sort()) {
    const name = file.replace(/\.js$/, ""), source = fs.readFileSync(path.join(dir, file), "utf8").trimEnd(), base = "/work/" + name;
    fs.mkdirSync(base); uncaught = []; if (process.env.PROGRESS) console.error(name);
    const body = new Function("fs", "h", "return (async () => {" + source + "\n})()");
    // A scenario that waits for an event that never comes is a failure, not a quiet exit.
    const alarm = setTimeout(() => { console.error("scenario " + name + " did not finish"); process.exit(1); }, 10000);
    try { scenarios[name] = { source, result: JSON.parse(JSON.stringify(await body(fs, helpers(base)))) }; } catch (error) { throw new Error("scenario " + name + " failed", { cause: error }); }
    clearTimeout(alarm);
    await new Promise(resolve => setTimeout(resolve, 20));
  }
  const lifetime = {};
  fs.mkdirSync("/work/lifetime");
  for (const [name, source] of Object.entries(LIFETIME)) {
    const run = child.spawnSync(process.execPath, ["-e", source], { encoding: "utf8", timeout: 20000 });
    lifetime[name] = { source, status: run.status, signal: run.signal, stdout: run.stdout.trim(), stderr: run.stderr.split("\n").filter(line => /^\w*Error|code:/.test(line.trim())).map(line => line.trim()) };
  }
  fs.writeFileSync(1, JSON.stringify({ node: process.version, recorder: fs.readFileSync(__filename, "utf8"), scenarios, lifetime }, null, 1) + "\n");
  process.exit(0);
})().catch(error => { console.error(error); process.exit(1); });

append.source:
const U = fs.Utf8Stream, f = h.dir + "/a.log", g = h.dir + "/b.log", k = h.dir + "/c.log";
for (const path of [f, g, k]) fs.writeFileSync(path, "old\n");
const results = {};
for (const [path, options] of [[f, {}], [g, { append: false }], [k, { append: false, sync: true }]]) {
  const s = new U({ dest: path, ...options });
  const state = h.state(s);
  s.write("new\n"); s.end();
  await h.event(s, "close");
  results[path.slice(-5)] = [state.append, h.text(path)];
}
return results;

async-basic.source:
const U = fs.Utf8Stream, f = h.dir + "/a.log";
const s = new U({ dest: f }), seen = h.log(s);
const before = h.state(s);
const returns = [s.write("hello "), s.write("world\n")], writingBeforeReady = s.writing;
await h.event(s, "drain");
const afterDrain = { state: h.state(s), text: h.text(f) };
returns.push(s.write("again\n"));
await h.event(s, "drain");
returns.push(s.end());
await h.event(s, "close");
return { before, returns, writingBeforeReady, afterDrain, seen, text: h.text(f), after: h.state(s) };

