const returns = [s.write(h.Buffer.from("one\n")), s.write(h.Buffer.from("two\n")), s.write(h.Buffer.from("three\n"))];
await h.turns();
const middle = { text: h.text(f), uncaught: h.uncaught.slice(), seen: seen.slice(), state: h.state(s) };
const later = h.attempt(() => s.write(h.Buffer.from("four\n")));
await h.turns();
const end = h.attempt(() => s.end());
await h.turns();
return { state, returns, middle, later, end, uncaught: h.uncaught.slice(), seen, text: h.text(f), after: h.state(s) };

