drain-sync.source:
const U = fs.Utf8Stream, f = h.dir + "/a.log";
const s = new U({ dest: f, sync: true }), order = [];
s.write("a\n"); s.write("b\n");
await h.turns();
s.on("drain", () => order.push("drain 1"));
await h.turns();
order.push("listener added, nothing yet");
s.write("c\n"); s.write("d\n"); order.push("wrote");
await h.turns();
s.on("drain", () => order.push("drain 2"));
s.write("e\n");
await h.turns();
const a = new U({ dest: h.dir + "/b.log" }), asyncOrder = [];
a.on("drain", () => asyncOrder.push("drain"));
a.on("ready", () => asyncOrder.push("ready"));
await h.turns();
a.write("x\n"); asyncOrder.push("wrote");
await h.turns();
s.destroy(); a.destroy();
return { order, asyncOrder };

eagain-async.source:
const U = fs.Utf8Stream, f = h.dir + "/a.log", calls = [], retries = [];
let failures = 2;
const s = new U({ dest: f, retryEAGAIN: (error, writing, remaining) => { retries.push([error.code, writing, remaining]); return true; }, fs: { write(fd, data, encoding, callback) {
  calls.push([typeof fd, data, encoding, typeof callback]);
  if (failures-- > 0) { setImmediate(() => callback(Object.assign(new Error(failures === 1 ? "again" : "busy"), { code: failures === 1 ? "EAGAIN" : "EBUSY" }))); return; }
  fs.write(fd, data, null, encoding, callback);
} } }), seen = h.log(s);
await h.event(s, "ready");
const returns = [s.write("retry me\n"), s.write("and me\n")];
await h.turns();
const first = { seen: seen.slice(), calls: calls.length, retries: retries.slice(), writing: s.writing, text: h.text(f) };
await h.sleep(100);
const second = { calls: calls.length, retries: retries.slice(), text: h.text(f) };
await h.sleep(100);
s.end();
await h.event(s, "close");
return { returns, first, second, calls, retries, seen, text: h.text(f) };

eagain-refused.source:
