let failures = 1;
const s = new U({ dest: f, retryEAGAIN: (error, writing, remaining) => { retries.push([error.code, writing, remaining]); return false; }, fs: { write(fd, data, encoding, callback) {
  if (failures-- > 0) { setImmediate(() => callback(Object.assign(new Error("again"), { code: "EAGAIN" }))); return; }
  fs.write(fd, data, null, encoding, callback);
} } }), seen = h.log(s);
await h.event(s, "ready");
s.write("one\n"); s.write("two\n");
const error = await h.event(s, "error");
const state = h.state(s);
const next = s.write("three\n");
await h.event(s, "drain");
s.end();
await h.event(s, "close");
return { error, retries, state, next, seen, text: h.text(f) };

eagain-sync.source:
const U = fs.Utf8Stream, f = h.dir + "/a.log", retries = [], calls = [];
let failures = 2, refuse = false;
const s = new U({ dest: f, sync: true, retryEAGAIN: (error, writing, remaining) => { retries.push([error.code, writing, remaining]); return !refuse; }, fs: { writeSync(fd, data, encoding) {
  calls.push([data, encoding]);
  if (failures-- > 0) throw Object.assign(new Error("again"), { code: "EAGAIN" });
  return fs.writeSync(fd, data, null, encoding);
} } }), seen = h.log(s);
const started = Date.now();
const returns = [s.write("retry me\n")], waited = Date.now() - started >= 190, text = h.text(f);
failures = 1; refuse = true;
returns.push(h.attempt(() => s.write("refused\n")));
const afterRefusal = { seen: seen.slice(), state: h.state(s), text: h.text(f) };
returns.push(s.write("next\n"));
failures = 1; refuse = false; s.write("flushed\n"); 
failures = 1; const flushSync = h.attempt(() => s.flushSync());
failures = 1; refuse = true; s.write("z\n");
const flushRefused = h.attempt(() => s.flushSync());
failures = 1; const other = Object.assign(new Error("io"), { code: "EIO" });
await h.turns();
s.end();
await h.event(s, "close");
return { returns, waited, text, afterRefusal, flushSync, flushRefused, retries, calls, seen, final: h.text(f) };

