fs-calls.source:
const U = fs.Utf8Stream, f = h.dir + "/a.log", calls = [];
const shape = value => typeof value === "function" ? "function" : h.Buffer.isBuffer(value) ? { hex: value.toString("hex") } : typeof value === "number" && value > 2 ? "fd" : value === undefined ? "undefined" : value;
const spy = {};
for (const name of ["open", "write", "fsync", "close", "mkdir"]) spy[name] = function (...args) { calls.push([name, this === spy, ...args.map(shape)]); return name === "write" && typeof args[1] === "string" ? fs.write(args[0], args[1], null, args[2], args[3]) : fs[name](...args); };
for (const name of ["openSync", "writeSync", "fsyncSync", "mkdirSync"]) spy[name] = function (...args) { calls.push([name, ...args.map(shape)]); return name === "writeSync" && typeof args[1] === "string" ? fs.writeSync(args[0], args[1], null, args[2]) : fs[name](...args); };
const run = async options => { calls.length = 0; const s = new U({ fs: spy, ...options }); s.write(options.contentMode === "buffer" ? h.Buffer.from("x\n") : "x\n"); await h.turns(); try { s.flushSync(); } catch {} await new Promise(resolve => { s.flush(resolve); if (!options.minLength) resolve(); }); await h.turns(); try { s.end(); } catch {} await h.turns(); return calls.slice(); };
return { async: await run({ dest: f, mkdir: true, mode: 0o600 }), sync: await run({ dest: f, sync: true, mkdir: true, append: false }), buffered: await run({ dest: f, minLength: 10, fsync: true }), buffer: await run({ dest: h.dir + "/b.log", contentMode: "buffer", minLength: 10 }) };

fsync-failure.source:
const U = fs.Utf8Stream, f = h.dir + "/a.log";
let code = "EIO", thrown = false;
const s = new U({ dest: f, minLength: 10, fs: { fsync(fd, callback) { if (thrown) throw Object.assign(new Error("thrown"), { code: "EINVAL" }); if (code === null) return fs.fsync(fd, callback); setImmediate(() => callback(Object.assign(new Error("sync failed"), { code }))); },
  fsyncSync() { throw Object.assign(new Error("sync failed"), { code: "EIO" }); } } }), seen = h.log(s);
await h.event(s, "ready");
const flush = () => new Promise(resolve => s.flush((...args) => resolve(args.map(h.show))));
s.write("a\n"); const failed = await flush();
code = "EBADF"; s.write("b\n"); const ignored = await flush();
thrown = true; s.write("c\n"); const threw = await flush();
s.write("d\n"); const flushSync = h.attempt(() => s.flushSync());
const text = h.text(f);
s.end();
await h.turns();
const swallowed = { seen: seen.slice(), state: h.state(s) };
thrown = false; code = null;
return { failed, ignored, threw, flushSync, text, swallowed, uncaught: h.uncaught };

fsync-option.source:
