const counting = { fsyncSync(fd) { calls.push("fsyncSync"); return fs.fsyncSync(fd); }, fsync(fd, callback) { calls.push("fsync"); return fs.fsync(fd, callback); } };
const s = new U({ dest: f, fsync: true, minLength: 10, fs: counting }), seen = h.log(s);
await h.event(s, "ready");
const state = h.state(s);
s.write("0123456789abc\n");
await h.event(s, "drain");
const afterWrite = calls.slice();
await new Promise(resolve => s.flush(resolve));
const afterFlush = calls.slice();
s.flushSync();
const afterFlushSync = calls.slice();
s.end();
await h.event(s, "close");
const plain = new U({ dest: h.dir + "/b.log", minLength: 10, fs: counting }); calls.length = 0;
await h.event(plain, "ready");
plain.write("x\n");
await new Promise(resolve => plain.flush(resolve));
const plainFlush = calls.slice();
plain.flushSync(); plain.end();
await h.event(plain, "close");
return { state, afterWrite, afterFlush, afterFlushSync, all: calls, plainFlush, seen };

fsync-sync-failure.source:
const U = fs.Utf8Stream, f = h.dir + "/a.log";
const failing = { fsyncSync() { throw Object.assign(new Error("sync failed"), { code: "EIO" }); } };
